/** @jest-environment node */

const { flatToNested } = require('../flatToNested');

describe('flatToNested', () => {
  it('converts dot-separated keys into nested objects', () => {
    expect(flatToNested({ 'homePage.title': 'Home' })).toEqual({
      homePage: { title: 'Home' },
    });
  });

  it('handles deeply nested keys', () => {
    expect(flatToNested({ 'a.b.c': 'value' })).toEqual({
      a: { b: { c: 'value' } },
    });
  });

  it('overwrites intermediate string values to allow deeper nesting', () => {
    expect(
      flatToNested({
        'hub-catalog.homePage': 'legacy',
        'hub-catalog.homePage.title': 'Home',
      })
    ).toEqual({
      'hub-catalog': { homePage: { title: 'Home' } },
    });
  });

  it('returns empty object for empty input', () => {
    expect(flatToNested({})).toEqual({});
  });
});
